mapper.select:
SELECT kb_id, tenant_id, kb_name, description, embedding_model, status, create_time
FROM kb_knowledge_base WHERE tenant_id = #{tenantId}
ORDER BY create_time DESC

mapper.update:
UPDATE kb_knowledge_base
SET kb_name = #{kbName},
    description = #{description},
    embedding_model = #{embeddingModel},
    status = #{status}
WHERE kb_id = #{kbId}
